from django.db import migrations, models

import speakers.encryption


def copy_speakers_pretix(apps, schema_editor):
    """Carry the speakers' per-edition Pretix settings over (decision 0012).
    A token or secret this deploy cannot decrypt is left behind: it could
    not be written again, and the edition reads as not configured anyway."""
    SpeakerSettings = apps.get_model("speakers", "SpeakerSettings")
    TicketingSettings = apps.get_model("ticketing", "TicketingSettings")
    for row in SpeakerSettings.objects.select_related("conference"):
        if not (row.pretix_organizer or row.pretix_api_token):
            continue

        def readable(value):
            return value if isinstance(value, str) else ""

        TicketingSettings.objects.get_or_create(
            conference=row.conference,
            defaults={
                "provider": "PRETIX",
                "base_url": row.pretix_base_url,
                "organizer": row.pretix_organizer,
                "event_id": row.pretix_event or row.conference.pretix_event_slug,
                "api_token": readable(row.pretix_api_token),
                "webhook_secret": readable(row.pretix_webhook_secret),
                "last_synced_at": row.pretix_last_synced_at,
            },
        )


